const raw = $input.first().json.output;

// Memperbaiki karakter kontrol di dalam string JSON
function repairJsonString(str) {
  let result = '';
  let insideString = false;
  let escaped = false;

  for (let i = 0; i < str.length; i++) {
    const char = str[i];

    if (insideString) {
      if (escaped) {
        result += char;
        escaped = false;
        continue;
      }

      if (char === '\\') {
        result += char;
        escaped = true;
        continue;
      }

      if (char === '"') {
        result += char;
        insideString = false;
        continue;
      }

      if (char === '\n') {
        result += '\\n';
        continue;
      }

      if (char === '\r') {
        result += '\\r';
        continue;
      }

      if (char === '\t') {
        result += '\\t';
        continue;
      }

      result += char;
    } else {
      result += char;

      if (char === '"') {
        insideString = true;
      }
    }
  }

  return result;
}

let parsed;

try {
  if (typeof raw !== 'string' || !raw.trim()) {
    throw new Error('Output AI kosong atau bukan string');
  }

  parsed = JSON.parse(repairJsonString(raw.trim()));
} catch (e) {
  return [{
    json: {
      error: e.message,
      raw: raw ?? null
    }
  }];
}

const data = parsed.data || {};

// Normalisasi jenis penumpang
const validTypes = ['adult', 'child', 'infant'];

const passengers = Array.isArray(data.passengers)
  ? data.passengers.map(p => ({
      name: p?.name
        ? String(p.name).trim().toUpperCase()
        : null,

      type: validTypes.includes(
        String(p?.type ?? '').toLowerCase()
      )
        ? String(p.type).toLowerCase()
        : null,

      phone: p?.phone ?? null
    }))
  : null;

// Identifikasi penumpang yang datanya belum lengkap
const incompletePassengers = Array.isArray(passengers)
  ? passengers.some(p => !p.name || !p.type)
  : false;

// Pertahankan missing_fields dari AI,
// tambahkan passengers jika data penumpang belum lengkap.
const missingFields = Array.isArray(parsed.missing_fields)
  ? [...parsed.missing_fields]
  : [];

if (incompletePassengers && !missingFields.includes('passengers')) {
  missingFields.push('passengers');
}

return [{
  json: {
    intent: parsed.intent ?? null,
    status: parsed.status ?? null,
    reply: parsed.reply ?? '',
    route: data.route ?? null,
    date: data.date ?? null,
    order_date: data.order_date ?? null,
    passengers,
    missing_fields: missingFields
  }
}];

const data = $("Cek seat").item.json;

const formatDate = (date) => {
  return new Intl.DateTimeFormat('id-ID', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    year: 'numeric',
    timeZone: 'Asia/Makassar'
  }).format(new Date(date + 'T00:00:00+08:00'));
};

const routeNames = {
  'MNA-IAX': 'Melonguane - Miangas',
  'MNA-MDC': 'Melonguane - Manado'
};

const route = routeNames[data.route] || data.route;
const requestedDate = data.date ? formatDate(data.date) : '-';
const alternatives = Array.isArray(data.alternatives)
  ? data.alternatives
  : [];

let reply = '';

if (
  (data.status === 'available' || data.status === 'collecting') &&
  Number(data.booked) < 10
){
   const sisaKursi = Math.max(10 - (data.booked), 0);
   reply =
     `✈️ *JADWAL PENERBANGAN TERSEDIA*\n\n` +
     `Rute: *${route}*\n` +
     `Tanggal: *${requestedDate}*\n` +
     `Sisa kursi: *${sisaKursi} seat*\n\n`;
}
else if (data.status === 'collecting') {
   const sisaKursi = Math.max(10 - (data.booked), 0);
   reply =
     `✈️ *JADWAL PENERBANGAN TERSEDIA*\n\n` +
     `Rute: *${route}*\n` +
     `Tanggal: *${requestedDate}*\n` +
     `Sisa kursi: *${sisaKursi} seat*\n\n`;
}
else if (data.status === 'full' || data.booked > 9) {
  reply =
    `Mohon maaf, penerbangan untuk\n\n` +
    `Rute: *${route}*\n` +
    `Tanggal: *${requestedDate}*\n\n` +
    ` Sudah *PENUH/FULL*\n\n`;
}
else if (data.status === 'no_schedule') {
  reply =
    `Mohon maaf, tidak ada jadwal penerbangan pada tanggal tersebut.\n\n` +
    `Rute: *${route}*\n` +
    `Tanggal: *${requestedDate}*\n\n`;
}
else if (data.status === 'booking_not_open') {
  reply = 'Mohon maaf, pemesanan untuk bulan berikutnya belum dibuka.';
}
else {
  reply = data.message || data.error ||
    'Maaf, terjadi kesalahan saat memeriksa jadwal penerbangan.';
}

// Tampilkan seluruh alternatif penerbangan sampai akhir bulan
if (['available', 'full', 'no_schedule', 'collecting'].includes(data.status)) {

  reply += `📅 *REKOMENDASI JADWAL PENERBANGAN*\n`;
  reply += `Rute: *${route}*\n\n`;

  if (alternatives.length > 0) {
    reply += alternatives.map((item, index) => {
      const seats = item.availableSeats ?? item.available ?? 0;

      return (
        `${index + 1}. *${formatDate(item.date)}*\n` +
        `    💺 Kursi tersedia: *${seats} seat*`
      );
    }).join('\n\n');

  } else {
    reply += 'Belum ada jadwal alternatif yang tersedia sampai akhir bulan ini.';
  }

  reply += '\n\n*Catatan:* Ketersediaan kursi dapat berubah sewaktu-waktu sesuai dengan proses pemesanan pelanggan lain yang masuk. Silakan balas dengan memilih tanggal penerbangan yang diinginkan.';
}

return {
  json: {
    ...data,
    reply
  }
};

const items = $input.all();

const first = items[0].json;

return [{
  json: {
    ...first,
    total_penumpang: items.length
  }
}];

const text = $('WAHA Trigger').first().json.payload.body || "";

// Fungsi bantu regex universal
const extract = (regex, text, group = 1, defaultVal = 0) => {
  const match = text.match(regex);

  if (!match) return defaultVal;

  return isNaN(match[group])
    ? match[group].trim()
    : Number(match[group]);
};

// 1. Ekstrak Tanggal
const dateMatch = text.match(/(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})/);

let day = 2;
let month = 11;
let year = 2026;

const months = {
  jan: 1, feb: 2, mar: 3, apr: 4,
  may: 5, jun: 6, jul: 7, aug: 8,
  sep: 9, oct: 10, nov: 11, dec: 12
};

if (dateMatch) {
  day = parseInt(dateMatch[1]);
  month = months[dateMatch[2].toLowerCase()] || 11;
  year = parseInt(dateMatch[3]);
}

// 2. Ekstrak Rute
const routeMatch = text.match(/Route\s*:\s*(.+)/i);

let route = routeMatch ? routeMatch[1].trim() : "MNA-MDC";

// Hilangkan spasi di sekitar tanda hubung
route = route.replace(/\s*-\s*/g, '-');

// 3. Ekstrak Pax: Adult / Child / Infant dan Berat Penumpang
const paxMatch = text.match(
  /Pax\s*:\s*(\d+)\s*\/\s*(\d+)\s*\/\s*(\d+)\s*\(\s*(\d+)\s*\)/i
);

const adult = paxMatch ? Number(paxMatch[1]) : 0;
const child = paxMatch ? Number(paxMatch[2]) : 0;
const infant = paxMatch ? Number(paxMatch[3]) : 0;

const paxCount = adult + child + infant;

const passengerWeight = paxMatch
  ? Number(paxMatch[4])
  : 0;

// 4. Ekstrak Bagasi
const baggageWeight = extract(
  /Bags\s*:\s*(\d+)\s*Kg/i,
  text
);

const baggagePieces = extract(
  /Bags\s*:\s*\d+\s*Kg\s*\(\s*(\d+)\s*coli\s*\)/i,
  text
);

// 5. Ekstrak Hand Carry / Cabin
const cabinWeight = extract(
  /Hc\s*:\s*(\d+)\s*Kg/i,
  text
);

const cabinPieces = extract(
  /Hc\s*:\s*\d+\s*Kg\s*\(\s*(\d+)\s*coli\s*\)/i,
  text
);

// 6. Ekstrak Kargo / Ebt
const cargoWeight = extract(
  /(?:Cargo\s+SA|Ebt)\s*:\s*(\d+)\s*Kg/i,
  text
);

const cargoPieces = extract(
  /(?:Cargo\s+SA|Ebt)\s*:\s*\d+\s*Kg\s*\(\s*(\d+)\s*coli\s*\)/i,
  text
);

// 7. Output
return [
  {
    json: {
      billing_year: year,
      billing_month: month,
      replace_period: true,
      flights: [
        {
          flight_day: day,
          route: route,

          // Data penumpang
          pax: paxCount,
          adult: adult,
          child: child,
          infant: infant,
          passenger_weight: passengerWeight,

          // Bagasi
          baggage_pieces: Number(baggagePieces),
          baggage_weight: Number(baggageWeight),

          // Hand Carry
          cabin_baggage_pieces: Number(cabinPieces),
          cabin_baggage_weight: Number(cabinWeight),

          // Kargo
          cargo_pieces: Number(cargoPieces || 0),
          cargo_weight: Number(cargoWeight || 0)
        }
      ]
    }
  }
];

const items = $input.all();

return [{
  json: {
    total_items: items.length,
    data: items.map(item => item.json)
  }
}];

